      "director": "Matías Piñeiro",
      "year": 2024,
      "duration": 6,
      "poster": "https://a.ltrbxd.com/resized/film-poster/1/0/8/5/7/4/9/1085749-you-burn-me-0-500-0-750-crop.jpg?v=3d7e1db678",
